import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA kernel: simple batched GEMM (fp16 inputs, fp32 accumulation, fp16 output)
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void batched_gemm_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int batch,
    int M,
    int N,
    int K)
{
    // batch dimension is mapped to blockIdx.z
    int b = blockIdx.z;
    if (b >= batch) return;

    // compute row / column of the output matrix for this thread
    int row = blockIdx.y * blockDim.y + threadIdx.y; // 0 .. M-1
    int col = blockIdx.x * blockDim.x + threadIdx.x; // 0 .. N-1
    if (row >= M || col >= N) return;

    // offsets for the current batch
    size_t a_off = size_t(b) * M * K;
    size_t b_off = size_t(b) * K * N;
    size_t c_off = size_t(b) * M * N;

    float acc = 0.0f;
    // loop over K dimension
    for (int k = 0; k < K; ++k) {
        __half a_val = A[a_off + size_t(row) * K + k];
        __half b_val = B[b_off + size_t(k) * N + col];
        acc += __half2float(a_val) * __half2float(b_val);
    }

    C[c_off + size_t(row) * N + col] = __float2half(acc);
}

// ------------------------------------------------------------------
// C++ wrapper
// ------------------------------------------------------------------
torch::Tensor batched_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "inputs must be float16");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3,
                "inputs must be 3‑D tensors (batch, M, K) and (batch, K, N)");
    const int batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    TORCH_CHECK(B.size(0) == batch && B.size(1) == K,
                "B must have shape (batch, K, N)");
    const int N = B.size(2);

    auto C = torch::empty({batch, M, N},
                         torch::TensorOptions()
                             .dtype(torch::kFloat16)
                             .device(A.device()));

    const dim3 block(16, 16);
    const dim3 grid((N + block.x - 1) / block.x,
                    (M + block.y - 1) / block.y,
                    batch);

    batched_gemm_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        batch, M, N, K);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in batched_gemm_kernel: ", cudaGetErrorString(err));
    }
    return C;
}
'''

